 if(kind==='new-purchase'||kind==='purchase-material'){title='Purchase material';body=`<div class="formgrid">${select('Material','material',state.materials.map(m=>[m.id,`${m.name} · ${m.unit}`]),key,'required')}${select('Project','project',projectOpts(x=>!x.closed),'','required')}${field('Quantity','qty',12,'number','required min="0.01" max="100000" step="0.01"')}${field('Unit cost AED','cost',state.materials.find(m=>m.id===key)?.cost||3650,'number','required min="0.01" max="1000000" step="0.01"')}${field('Expected receipt','eta','2026-10-05','date','required')}${field('Supplier (fictional)','supplier',state.materials.find(m=>m.id===key)?.supplier||'Gulf Section Supply (demo)','text','required maxlength="150"')}</div>`;kind='purchase';}
 if(kind==='receive'){const po=state.purchases.find(x=>x.id===key);title='Material receipt';body=`${hidden('id',key)}<p>${po.id} · ${esc(name(po.project))}<br>Remaining: ${po.qty-po.received} units. Each receipt updates stock once.</p>${field('Received quantity','qty',po.qty-po.received,'number',`required min="0.01" max="${po.qty-po.received}" step="0.01"`)}`;}
 if(kind==='allocate'){title='Allocate steel';body=`${hidden('project',key)}<p>${esc(p.name)} requires ${p.material.required} tonnes; ${p.material.allocated} already allocated.</p><div class="formgrid">${select('Stock material','material',state.materials.filter(m=>m.unit==='tonne').map(m=>[m.id,`${m.name} · ${m.stock} tonnes available`]),'','required')}${field('Allocate tonnes','qty',p.material.required-p.material.allocated,'number',`required min="0.01" max="${p.material.required-p.material.allocated}" step="0.01"`)}</div><p>Allocation consumes warehouse stock. Drawings must be approved.</p>`;}
 if(kind==='new-package'){title='New work package';body=`<div class="formgrid">${select('Project','project',projectOpts(x=>x.accepted&&!x.closed),key,'required')}${field('Package name','name','Steel assembly','text','required maxlength="150"')}${field('Assembly target','qty',40,'number','required min="1" max="10000" step="1"')}${select('Workshop','owner',['Fabrication bay A','Fabrication bay B'])}</div>`;}
 if(kind==='work-progress'){const w=state.packages.find(x=>x.id===key);title='Fabrication progress';body=`${hidden('id',key)}<p>${esc(w.name)} · ${esc(name(w.project))}</p>${field('Total completed assemblies','done',w.done,'number',`required min="${w.done}" max="${w.qty}" step="1"`)}<p>Progress is cumulative; enter the total completed, up to ${w.qty}. Approved drawings and full material allocation are required.</p>`;}
