 if(kind==='quality'){const q=state.quality.find(x=>x.id===key);title='QA decision';body=`${hidden('id',key)}<p>${esc(q.inspection)} · ${esc(name(q.project))}</p><div class="formgrid">${select('Decision','status',['Pending','Hold','Released'],q.status)}${field('Evidence / remedial action','notes',q.notes,'textarea','required maxlength="2000"')}</div><p>Release requires completed fabrication. Any hold blocks dispatch.</p>`;}
 if(kind==='new-delivery'){title='New delivery';body=`<div class="formgrid">${select('Project','project',projectOpts(x=>x.accepted&&!x.closed),key,'required')}${field('Dispatch date','date',DATE,'date','required')}${field('Driver / logistics (demo)','driver','Demo logistics team','text','required maxlength="100"')}</div><p>The delivery includes all project assemblies. QA release, full fabrication, allocated material and approved drawings are required. One delivery is allowed per project in this demonstration.</p>`;}
 if(kind==='confirm-delivery'){const d=state.deliveries.find(x=>x.id===key);title='Confirm delivery';body=`${hidden('id',key)}<p>${d.id} · ${esc(name(d.project))} · ${d.qty} assemblies</p>${field('Site receipt note (simulated)','note','All assemblies received at site.','textarea','required maxlength="1000"')}`;}
 if(kind==='erection'){title='Erection progress';body=`${hidden('project',key)}<p>${esc(p.name)} · ${esc(p.site)}</p>${field('Total installation complete %','erected',p.erected,'number',`required min="${p.erected}" max="100" step="1"`)}${field('Site progress note','note','','textarea','required maxlength="1500"')}<p>Confirmed delivery is required before installation progress.</p>`;}
 if(kind==='handover'){title='Project handover';body=`${hidden('project',key)}<p>${esc(p.name)} · ${p.erected}% installed</p>${field('Site acceptance note (simulated)','note','Installation complete; snag list cleared.','textarea','required maxlength="1500"')}<p>This records a fictional handover. Erection must be 100% and QA released.</p>`;}
 if(kind==='new-invoice'){title='Milestone invoice';body=`<div class="formgrid">${select('Project','project',projectOpts(x=>x.accepted&&!x.closed),key,'required')}${select('Milestone','milestone',['LPO advance','Drawings approval','Materials delivered','Steel structure complete','Hand over','Agreed final-account adjustment'])}${field('Milestone percentage','percent',10,'number','required min="0.01" max="100" step="0.01"')}${field('Payment due','due','2026-10-17','date','required')}${field('Certification / adjustment note','note','','textarea','required maxlength="1500"')}</div><p>Source presets: 10 / 40 / 25 / 15 / 5 = 95%. A final-account adjustment needs its own explicit agreement note. Billing cannot exceed contract value.</p>`;}
 if(kind==='payment'){const inv=state.invoices.find(x=>x.id===key);title='Sample payment';body=`${hidden('invoice',key)}<p>${inv.id} · ${esc(name(inv.project))}<br>Outstanding: AED ${money(outstanding(inv))}</p><div class="formgrid">${field('Sample amount AED','amount',outstanding(inv),'number',`required min="0.01" max="${outstanding(inv)}" step="0.01"`)}${select('Method (simulated)','method',['Sample bank transfer','Sample cheque','Sample cash receipt'])}</div><p>No payment is charged, transmitted or processed.</p>`;}
