 if(kind==='new-task'){title='New task';body=`<div class="formgrid">${select('Project','project',projectOpts(x=>!x.closed),key,'required')}${field('Task title','title','','text','required maxlength="160"')}${select('Owner','owner',['Samir Ali','Nadia Karim'])}${field('Due date','due',DATE,'date','required')}</div>`;}
 if(kind==='closeout'){title='Project closeout';const checks=['As-built drawings','QA dossier','Warranty & maintenance guide','Final account'];body=`${hidden('project',key)}<p>${esc(p.name)} · Outstanding AED ${money(pOutstanding(p))}</p>${checks.map(x=>`<div class="checkrow"><input type="checkbox" id="check-${checks.indexOf(x)}" name="checklist" value="${esc(x)}" ${p.checklist.includes(x)?'checked':''}><label for="check-${checks.indexOf(x)}">${esc(x)}</label></div>`).join('')}<p>Saving keeps the checklist. Close project additionally requires all four documents, handover, fully billed contract and no outstanding balance.</p><div class="actions"><label><input style="width:auto" name="close" type="checkbox"> Close project after validation</label></div>`;}
 if(!body)throw new Error('This record is unavailable. Refresh and try again.');openDialog(title,body,kind);
